-- Import one batch of JED3 revisions into #__jed_extensions_history.
-- {{BATCH}} is substituted by the plugin - this one file backs every history import step.
--
-- Batches are equal by ROW COUNT, not by id range: the boundaries in
-- combine_jed_history_batches come from NTILE, so every step does the same amount of work.
-- An id-range midpoint would be badly skewed whenever the JED revisions cluster in one part
-- of wqyh6_ucm_history, which is exactly what made the earlier two-way split time out.
--
-- Revisions already recorded in combine_jed_history_done are skipped, so re-running a step
-- after a browser timeout cannot import the same revision twice.
--
-- description is taken from the revision verbatim and intro is left empty. Both are put into
-- the shape #__jed_extensions holds - tags stripped, entities decoded, Markdown normalised,
-- intro derived - by history_baseline.sql, which runs once after the last batch. Doing it
-- there rather than per row here keeps a revision diffable against the live listing: a
-- description that differs only in markup handling would otherwise show up as an edit.
INSERT INTO #__jed_extensions_history (extension_id, active, name, alias, catid, owner, state, approved, approved_time, approved_notes, approved_reason, intro, description, license, license_url, requires_registration, type, extension_types, created, created_by, modified, modified_by, checked_out, checked_out_time, extension_version, joomla_versions, download_url, support_url, demo_url, documentation_url, git_url, internal_download_url, download_key, uses_updater, update_url, developer_url, developer_email, changelog_url, score_overall, score_functionality, score_ease_of_use, score_support, score_documentation, score_value_for_money, score_count, popular, logo, video, internal_note) SELECT m.extension_id, 0, LEFT(COALESCE(NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(h.version_data, '$.core_title')), 'null'), ''), NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(h.version_data, '$.title')), 'null'), ''), e.name), 255), LEFT(COALESCE(NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(h.version_data, '$.core_alias')), 'null'), ''), NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(h.version_data, '$.alias')), 'null'), ''), e.alias), 255), COALESCE(CASE WHEN NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(h.version_data, '$.core_catid')), 'null'), '') REGEXP '^-?[0-9]+$' THEN CAST(NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(h.version_data, '$.core_catid')), 'null'), '') AS SIGNED) END, CASE WHEN NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(h.version_data, '$.catid')), 'null'), '') REGEXP '^-?[0-9]+$' THEN CAST(NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(h.version_data, '$.catid')), 'null'), '') AS SIGNED) END, e.catid), COALESCE(CASE WHEN NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(h.version_data, '$.core_created_user_id')), 'null'), '') REGEXP '^-?[0-9]+$' THEN CAST(NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(h.version_data, '$.core_created_user_id')), 'null'), '') AS SIGNED) END, CASE WHEN NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(h.version_data, '$.created_by')), 'null'), '') REGEXP '^-?[0-9]+$' THEN CAST(NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(h.version_data, '$.created_by')), 'null'), '') AS SIGNED) END, e.owner), CASE WHEN COALESCE(CASE WHEN NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(h.version_data, '$.core_state')), 'null'), '') REGEXP '^-?[0-9]+$' THEN CAST(NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(h.version_data, '$.core_state')), 'null'), '') AS SIGNED) END, CASE WHEN NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(h.version_data, '$.state')), 'null'), '') REGEXP '^-?[0-9]+$' THEN CAST(NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(h.version_data, '$.state')), 'null'), '') AS SIGNED) END, e.state) = 1 THEN 1 ELSE 0 END, e.approved, e.approved_time, e.approved_notes, e.approved_reason, '', COALESCE(NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(h.version_data, '$.core_body')), 'null'), ''),NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(h.version_data, '$.description')), 'null'), ''), e.description), LEFT(COALESCE(NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(h.version_data, '$.license')), 'null'), ''), e.license), 255), LEFT(COALESCE(NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(h.version_data, '$.license_link')), 'null'), ''), e.license_url), 255), COALESCE(CASE WHEN NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(h.version_data, '$.requires_registration')), 'null'), '') REGEXP '^-?[0-9]+$' THEN CAST(NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(h.version_data, '$.requires_registration')), 'null'), '') AS SIGNED) END, e.requires_registration), e.type, LEFT(COALESCE(NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(h.version_data, '$.includes')), 'null'), ''), e.extension_types), 255), COALESCE(STR_TO_DATE(NULLIF(REGEXP_SUBSTR(IFNULL(COALESCE(NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(h.version_data, '$.core_created_time')), 'null'), ''), NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(h.version_data, '$.created')), 'null'), '')), ''), '^[1-9][0-9]{3}-[0-9]{2}-[0-9]{2}([ ][0-9]{2}:[0-9]{2}:[0-9]{2})?'), ''), '%Y-%m-%d %H:%i:%s'), e.created), COALESCE(CASE WHEN NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(h.version_data, '$.core_created_user_id')), 'null'), '') REGEXP '^-?[0-9]+$' THEN CAST(NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(h.version_data, '$.core_created_user_id')), 'null'), '') AS SIGNED) END, CASE WHEN NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(h.version_data, '$.created_by')), 'null'), '') REGEXP '^-?[0-9]+$' THEN CAST(NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(h.version_data, '$.created_by')), 'null'), '') AS SIGNED) END, e.created_by), COALESCE(NULLIF(h.save_date, '0000-00-00 00:00:00'), e.modified), COALESCE(NULLIF(h.editor_user_id, 0), e.modified_by), NULL, NULL, LEFT(COALESCE(NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(h.version_data, '$.version')), 'null'), ''), e.extension_version), 50), LEFT(COALESCE(NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(h.version_data, '$.versions')), 'null'), ''), e.joomla_versions), 255), LEFT(COALESCE(NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(h.version_data, '$.download_link')), 'null'), ''), e.download_url), 255), LEFT(COALESCE(NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(h.version_data, '$.support_link')), 'null'), ''), e.support_url), 255), LEFT(COALESCE(NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(h.version_data, '$.demo_link')), 'null'), ''), e.demo_url), 255), LEFT(COALESCE(NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(h.version_data, '$.documentation_link')), 'null'), ''), e.documentation_url), 255), e.git_url, LEFT(COALESCE(NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(h.version_data, '$.extension_file')), 'null'), ''), e.internal_download_url), 255), e.download_key, COALESCE(CASE WHEN NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(h.version_data, '$.uses_updater')), 'null'), '') REGEXP '^-?[0-9]+$' THEN CAST(NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(h.version_data, '$.uses_updater')), 'null'), '') AS SIGNED) END, e.uses_updater), LEFT(COALESCE(NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(h.version_data, '$.update_url')), 'null'), ''), e.update_url), 255), LEFT(COALESCE(NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(h.version_data, '$.homepage_link')), 'null'), ''), e.developer_url), 255), LEFT(COALESCE(NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(h.version_data, '$.second_contact_email')), 'null'), ''), e.developer_email), 255), e.changelog_url, e.score_overall, e.score_functionality, e.score_ease_of_use, e.score_support, e.score_documentation, e.score_value_for_money, e.score_count, COALESCE(CASE WHEN NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(h.version_data, '$.popular')), 'null'), '') REGEXP '^-?[0-9]+$' THEN CAST(NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(h.version_data, '$.popular')), 'null'), '') AS SIGNED) END, e.popular), e.logo, LEFT(COALESCE(NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(h.version_data, '$.video')), 'null'), ''), e.video), 255), COALESCE(NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(h.version_data, '$.jed_note')), 'null'), ''), e.internal_note) FROM wqyh6_ucm_history h INNER JOIN combine_jed_history_map m ON m.ucm_item_id = h.ucm_item_id INNER JOIN #__jed_extensions e ON e.id = m.extension_id LEFT JOIN combine_jed_history_done d ON d.version_id = h.version_id WHERE h.ucm_type_id = (SELECT ucm_type_id FROM combine_jed_history_cfg) AND h.version_id BETWEEN (SELECT lo FROM combine_jed_history_batches WHERE batch = {{BATCH}}) AND (SELECT hi FROM combine_jed_history_batches WHERE batch = {{BATCH}}) AND d.version_id IS NULL AND JSON_VALID(h.version_data) ORDER BY h.save_date ASC, h.version_id ASC;

-- Record every revision in this batch as processed, including any skipped for invalid JSON.
INSERT IGNORE INTO combine_jed_history_done (version_id)
SELECT h.version_id FROM wqyh6_ucm_history h
INNER JOIN combine_jed_history_map m ON m.ucm_item_id = h.ucm_item_id
WHERE h.ucm_type_id = (SELECT ucm_type_id FROM combine_jed_history_cfg) AND h.version_id BETWEEN (SELECT lo FROM combine_jed_history_batches WHERE batch = {{BATCH}}) AND (SELECT hi FROM combine_jed_history_batches WHERE batch = {{BATCH}});
